import { ref, reactive } from 'vue'

// Vendored from web-linguist/packages/vue-i18n and reworked for build-time-only
// translation: locale maps are generated by bin/translate.js, committed to git
// under /src/locales/, and loaded as lazy chunks. The runtime makes ZERO
// network calls to WebLinguist.

export const currentLocale = ref('en')
export const messages = reactive({})

// Module-level config set by plugin install
let config = { sourceLanguage: 'en', targetLanguages: [] }

export function setConfig(cfg) {
  config = { ...config, ...cfg }
}

export function getConfig() {
  return config
}

// One async chunk per locale file; only the active locale ever loads.
const localeModules = import.meta.glob('/src/locales/*.json')

/**
 * Locale codes that have a generated translation file.
 * @returns {string[]}
 */
export function availableLocales() {
  return Object.keys(localeModules).map(p => p.match(/\/([^/]+)\.json$/)[1])
}

/**
 * Lazy-load a locale's flat {source: translated} map into the messages store.
 * @param {string} locale
 * @returns {Promise<boolean>} True if the locale is usable (source or loaded)
 */
export async function loadLocale(locale) {
  locale = locale.toLowerCase()
  if (locale === config.sourceLanguage || messages[locale]) return true
  const loader = localeModules[`/src/locales/${locale}.json`]
  if (!loader) return false
  loadLocaleMessages(locale, (await loader()).default)
  return true
}

/**
 * Translate a key string, with optional parameter interpolation.
 * Falls back to the key itself (the English source string) if no translation exists.
 *
 * @param {string} key - The English source string (used as key)
 * @param {Object} [params] - Interpolation parameters, e.g. { count: 5 }
 * @returns {string}
 */
export function t(key, params) {
  const locale = currentLocale.value
  const result = (messages[locale] && messages[locale][key]) || key
  return _interpolate(result, params)
}

/**
 * Set the active locale. Loads the locale file BEFORE flipping the reactive
 * locale so the UI never flashes untranslated. Persists to localStorage.
 *
 * @param {string} locale
 */
export async function setLocale(locale) {
  locale = locale.toLowerCase()
  await loadLocale(locale)
  currentLocale.value = locale

  try {
    localStorage.setItem('language', locale)
  } catch { /* storage unavailable */ }
}

/**
 * BCP47 locale for Intl date formatting (toLocaleDateString etc.), tracking
 * the active UI locale. Reactive when read inside computeds/templates.
 */
export function dateLocale() {
  const l = currentLocale.value
  return l === 'en' ? 'en-US' : l
}

/**
 * Load a locale's translations into the reactive messages store.
 *
 * @param {string} locale
 * @param {Object} data - Key-value map of English string → translated string
 */
export function loadLocaleMessages(locale, data) {
  locale = locale.toLowerCase()
  messages[locale] = { ...(messages[locale] || {}), ...data }
}

/**
 * Translate a dynamic (data-driven) string: pure lookup with source fallback.
 * Unknown strings render as their English source — no network, no error.
 *
 * @param {string} text - The source text to translate
 * @param {Object} [params] - Interpolation parameters
 * @returns {string}
 */
export function tDynamic(text, params) {
  // Collect BEFORE the source-language early return — play-testing happens in
  // English and strings must still reach the dev manifest.
  if (import.meta.env.DEV) _collect(text)
  const locale = currentLocale.value
  const hit = locale !== config.sourceLanguage && messages[locale] && messages[locale][text]
  return _interpolate(hit || text, params)
}

function _interpolate(str, params) {
  if (!params) return str
  for (const [k, v] of Object.entries(params)) {
    // Function replacement: a string replacement would interpret $$ / $& etc.
    // in values (e.g. money strings like "$4.5M") as replacement patterns.
    str = str.replace(new RegExp(`\\{${k}\\}`, 'g'), () => String(v))
  }
  return str
}

// --- Dev-mode dynamic-string collector (tree-shaken from prod builds) ---
let _seen = null
let _queue = null
let _collectTimer = null

function _collect(text) {
  if (!import.meta.env.DEV) return
  if (!text || typeof text !== 'string' || !text.trim() || text.includes('${')) return
  _seen ??= new Set()
  _queue ??= []
  if (_seen.has(text)) return
  _seen.add(text)
  _queue.push(text)
  clearTimeout(_collectTimer)
  _collectTimer = setTimeout(() => {
    const batch = _queue.splice(0)
    if (!batch.length) return
    fetch('/__wl-i18n/collect', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ strings: batch }),
    }).catch(() => {})
  }, 500)
}
